import type { LogContext, LogMiddleware } from "../interfaces.js";
/**
 * `tslog/throttle` — opt-in, tree-shakeable log de-duplication middleware (M4.7).
 *
 * Importing this module performs NO work and the core never references it: there is ZERO hot-path cost
 * unless you opt in with `logger.use(throttle({ windowMs }))`. Once attached, the middleware collapses
 * identical consecutive messages that arrive within `windowMs` into a single emitted log, then surfaces
 * how many were swallowed via a `repeated` count.
 *
 * How suppression + counting work:
 *
 * - The FIRST occurrence of a message passes through untouched and opens a window.
 * - Every IDENTICAL message within `windowMs` of the window's start is DROPPED (the middleware returns
 *   `null`, so nothing is formatted and no transport runs) and a private counter is incremented.
 * - The count is surfaced on the NEXT log that ends the run — either a DISTINCT message, or the same
 *   message arriving AFTER the window has elapsed. That log carries `repeated: N` (also mirrored onto its
 *   `_meta` block, since middleware-stashed `meta` is merged there) describing how many copies were
 *   suppressed since the window opened. A run that suppressed nothing carries no `repeated` field.
 *
 * "Identical" is decided by {@link IThrottleOptions.key}; the default key is a stable JSON-ish digest of
 * the log arguments, so `log.warn("disk full", { pct: 92 })` and an immediately-following identical call
 * collapse, while a different `pct` does not.
 *
 * Determinism: the pipeline injects no wall clock, and `Date.now` is real at runtime. For deterministic
 * tests pass `now: () => fakeMillis` to drive the window from your test's virtual clock.
 *
 * @example
 * import { Logger } from "tslog";
 * import { throttle } from "tslog/throttle";
 *
 * const log = new Logger({ type: "json" });
 * log.use(throttle({ windowMs: 1000 }));
 *
 * log.warn("rate limited");   // emitted
 * log.warn("rate limited");   // suppressed (within 1s)
 * log.warn("rate limited");   // suppressed
 * log.info("done");           // emitted, carries repeated: 2
 */
/** Options for the {@link throttle} middleware. All optional except {@link IThrottleOptions.windowMs}. */
export interface IThrottleOptions<LogObj = unknown> {
    /**
     * The de-duplication window in milliseconds. Identical messages within this many ms of the window's
     * start are suppressed; the first message after it elapses starts a fresh window. Non-positive values
     * disable suppression (every log passes, never any `repeated`).
     */
    windowMs: number;
    /**
     * Derive the identity key for a log. Two logs collapse iff they produce the same key. Defaults to a
     * stable digest of `context.args` ({@link defaultThrottleKey}). Return a stable string per logical
     * message (e.g. just the template, ignoring volatile fields) to tune what counts as "the same".
     */
    key?: (context: LogContext<LogObj>) => string;
    /**
     * The field name used to surface the suppressed count on the run-ending log. Defaults to `"repeated"`.
     * The value is set on `context.meta[field]`, which the core merges onto the record (and its `_meta`).
     */
    field?: string;
    /**
     * Injectable clock for deterministic testing. Defaults to {@link Date.now}. Must return milliseconds.
     */
    now?: () => number;
}
/**
 * Default {@link IThrottleOptions.key}: a stable, allocation-light digest of the log arguments.
 *
 * Each argument is reduced to a short tag — primitives by value, errors by name+message, everything else
 * by a depth-limited, key-sorted JSON pass (circular-safe) — and the tags are joined. This makes
 * structurally-identical calls (same message + same fields, regardless of object key order) collapse,
 * while any value difference yields a distinct key.
 */
export declare function defaultThrottleKey(context: LogContext<unknown>): string;
/**
 * Create an opt-in throttle/dedup {@link LogMiddleware}. Attach with `logger.use(throttle({ windowMs }))`.
 *
 * Off by default — the core never constructs this; only an explicit `use()` activates it. While active,
 * identical consecutive logs within `windowMs` are suppressed (dropped) and the suppressed count is
 * surfaced as `repeated: N` on the log that ends the run (a distinct message, or the same message after
 * the window elapses).
 *
 * @param opts - {@link IThrottleOptions}; only `windowMs` is required.
 * @returns a {@link LogMiddleware} to pass to `logger.use(...)`.
 */
export declare function throttle<LogObj = unknown>(opts: IThrottleOptions<LogObj>): LogMiddleware<LogObj>;
